<template><main class="zj-workspace"><header class="zj-heading"><div><div class="zj-eyebrow">众基消防 / 项目管理</div><h1>{{projectTypes[projectType]}}</h1><p>从合同到现场、报告和费用，按项目记录每一步。</p></div><el-button type="primary" icon="Plus" @click="create" v-hasPermi="['management:project:add']">创建项目并申请编号</el-button></header><section class="zj-card"><div class="zj-filters"><el-input v-model="query.name" placeholder="项目名称或编号" aria-label="项目搜索" clearable @keyup.enter="search"/><el-select v-model="query.pending" clearable placeholder="全部合同关联" aria-label="合同关联情况"><el-option label="待签订 / 待关联合同" value="1"/></el-select><el-button type="primary" icon="Search" @click="search">查询</el-button><el-button @click="reset">清空</el-button><el-button icon="Refresh" aria-label="刷新" @click="load"/></div></section><section class="zj-card"><div class="zj-summary">共 {{total}} 个项目</div><el-alert v-if="error" title="加载失败，请刷新重试" type="error" :closable="false"/><el-table v-loading="loading" :data="rows" empty-text="暂无项目，可先选择合同创建项目"><el-table-column label="项目" min-width="300"><template #default="{row}"><el-button link type="primary" class="zj-name" @click="detail(row)" v-hasPermi="['management:project:query']">{{row.projectName}}</el-button><div class="zj-sub">{{row.projectNo}}</div></template></el-table-column><el-table-column label="所属合同" min-width="240"><template #default="{row}"><span v-if="row.contractId">{{row.contractName}}</span><el-tag v-else type="warning">待签订 / 待关联合同</el-tag></template></el-table-column><el-table-column prop="leaderName" label="项目负责人" width="120"/><el-table-column label="迁移状态" width="160"><template #default="{row}"><el-tag v-if="row.classificationPending" type="warning" size="small">类型待确认</el-tag><el-tag v-if="row.numberPending" type="warning" size="small">编号待确认</el-tag><span v-if="!row.classificationPending&&!row.numberPending" class="zj-sub">正常</span></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click="detail(row)" v-hasPermi="['management:project:query']">打开项目</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @size-change="search" @current-change="load"/></section><el-drawer v-model="open" title="创建项目" size="min(780px, 96vw)" class="zj-drawer" :close-on-click-modal="false" :before-close="beforeClose"><el-alert title="合同未签订时可选择待签订。编号留空自动生成，也可填写甲方确认的编号；保存成功才占号。" type="info" :closable="false"/><h3>基本信息</h3><el-form label-position="top"><el-form-item label="项目编号（留空自动生成）"><el-input v-model="form.projectNo" maxlength="255" placeholder="可输入甲方确认的编号" :disabled="saving"/></el-form-item></el-form><ProjectBasicForm ref="formRef" v-model="form" :project-type="projectType" :disabled="saving"/><template #footer><el-button @click="beforeClose(()=>open=false)">取消</el-button><el-button type="primary" :loading="saving" @click="save">创建并申请编号</el-button></template></el-drawer></main></template>
<script setup>
import {projectList,createProject,projectTypes} from '@/api/workProject';import ProjectBasicForm from './ProjectBasicForm.vue';import '@/assets/styles/zhongji.scss';
const props=defineProps({projectType:String});const {proxy}=getCurrentInstance(),router=useRouter();const query=reactive({name:'',pending:'',pageNum:1,pageSize:20}),rows=ref([]),total=ref(0),loading=ref(false),error=ref(false),open=ref(false),saving=ref(false),form=ref({}),formRef=ref();let sequence=0,snapshot='';
async function load(){const n=++sequence;loading.value=true;error.value=false;try{const r=await projectList({...query,projectType:props.projectType});if(n===sequence){rows.value=r.rows;total.value=r.total;}}catch{if(n===sequence){rows.value=[];total.value=0;error.value=true;}}finally{if(n===sequence)loading.value=false;}}function search(){query.pageNum=1;load();}function reset(){query.name='';query.pending='';search();}function detail(row){router.push('/zhongji-project/'+row.id);}
function create(){form.value={projectNo:'',projectName:'',contractId:null,leaderUserId:null,technicalUserId:null,startDate:null,endDate:null};snapshot=JSON.stringify(form.value);open.value=true;}
async function beforeClose(done){if(saving.value)return;if(snapshot!==JSON.stringify(form.value)){try{await proxy.$modal.confirm('确认放弃未保存的项目信息？');}catch{return;}}done();}
async function save(){if(!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{const r=await createProject({...form.value,projectType:props.projectType});open.value=false;proxy.$modal.msgSuccess('项目已创建，编号：'+r.data.projectNo);await load();}finally{saving.value=false;}}onMounted(load);
</script>